window.__T={"n":[{"k":"levi","n":"Levi","t":"Son of Jacob, father of the tribe.","r":0,"c":0,"p":[],"m":1,"w":null,"i":"levi","sym":null,"v":[{"r":"Gen 29:34","t":"[34] And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi."},{"r":"Exo 6:16","t":"[16] And these are the names of the sons of Levi according to their generations; Gershon, and Kohath, and Merari: and the years of the life of Levi were an hundred thirty and seven years."}],"o":"","sc":[["the-assumption-of-moses","The Scroll of the Assumption of Moses"],["the-lost-messiahs","The Scroll of the Lost Messiahs"]]},{"k":"kohath","n":"Kohath","t":"Bore the holy things.","r":1,"c":0,"p":["levi"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Exo 6:16,18","t":"[16] And these are the names of the sons of Levi according to their generations; Gershon, and Kohath, and Merari: and the years of the life of Levi were an hundred thirty and seven years. [18] And the sons of Kohath; Amram, and Izhar, and Hebron, and Uzziel: and the years of the life of Kohath were an hundred thirty and three years."},{"r":"Num 4:4","t":"[4] This shall be the service of the sons of Kohath in the tabernacle of the congregation, about the most holy things:"}],"o":"","sc":[]},{"k":"gershon","n":"Gershon","t":"Bore the curtains.","r":1,"c":-1,"p":["levi"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"Num 3:25–26","t":"[25] And the charge of the sons of Gershon in the tabernacle of the congregation shall be the tabernacle, and the tent, the covering thereof, and the hanging for the door of the tabernacle of the congregation, [26] And the hangings of the court, and the curtain for the door of the court, which is by the tabernacle, and by the altar round about, and the cords of it for all the service thereof."}],"o":"","sc":[]},{"k":"merari","n":"Merari","t":"Bore the boards.","r":1,"c":1,"p":["levi"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"Num 3:36–37","t":"[36] And under the custody and charge of the sons of Merari shall be the boards of the tabernacle, and the bars thereof, and the pillars thereof, and the sockets thereof, and all the vessels thereof, and all that serveth thereto, [37] And the pillars of the court round about, and their sockets, and their pins, and their cords."}],"o":"","sc":[]},{"k":"amram","n":"Amram","t":"Father of Moses, Aaron and Miriam.","r":2,"c":0,"p":["kohath"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Exo 6:18,20","t":"[18] And the sons of Kohath; Amram, and Izhar, and Hebron, and Uzziel: and the years of the life of Kohath were an hundred thirty and three years. [20] And Amram took him Jochebed his father’s sister to wife; and she bare him Aaron and Moses: and the years of the life of Amram were an hundred and thirty and seven years."}],"o":"","sc":[]},{"k":"izhar","n":"Izhar","t":"Father of Korah.","r":2,"c":2,"p":["kohath"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"Exo 6:21","t":"[21] And the sons of Izhar; Korah, and Nepheg, and Zichri."}],"o":"","sc":[]},{"k":"moses","n":"Moses","t":"Consecrated Aaron and his sons.","r":3,"c":-2,"p":["amram"],"m":0,"w":null,"i":"moses","sym":null,"v":[{"r":"Exo 28:1","t":"[1] And take thou unto thee Aaron thy brother, and his sons with him, from among the children of Israel, that he may minister unto me in the priest’s office, even Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron’s sons."},{"r":"Lev 8:1–13","t":"[1] And the LORD spake unto Moses, saying, [2] Take Aaron and his sons with him, and the garments, and the anointing oil, and a bullock for the sin offering, and two rams, and a basket of unleavened bread; [3] And gather thou all the congregation together unto the door of the tabernacle of the congregation. [4] And Moses did as the LORD commanded him; and the assembly was gathered together unto the door of the tabernacle of the congregation. [5] And Moses said unto the congregation, This is the thing which the LORD commanded to be done. [6] And Moses brought Aaron and his sons, and washed them with water. [7] And he put upon him the coat, and girded him with the girdle, and clothed him with the robe, and put the ephod upon him, and he girded him with the curious girdle of the ephod, and bound it unto him therewith. [8] And he put the breastplate upon him: also he put in the breastplate the Urim and the Thummim. [9] And he put the mitre upon his head; also upon the mitre, even upon his forefront, did he put the golden plate, the holy crown; as the LORD commanded Moses. [10] And Moses took the anointing oil, and anointed the tabernacle and all that was therein, and sanctified them. [11] And he sprinkled thereof upon the altar seven times, and anointed the altar and all his vessels, both the laver and his foot, to sanctify them. [12] And he poured of the anointing oil upon Aaron’s head, and anointed him, to sanctify him. [13] And Moses brought Aaron’s sons, and put coats upon them, and girded them with girdles, and put bonnets upon them; as the LORD commanded Moses."}],"o":"","sc":[["the-assumption-of-moses","The Scroll of the Assumption of Moses"],["two-powers-in-heaven","The Scroll of the Two Powers in Heaven"],["the-heavenly-tablets","The Scroll of the Heavenly Tablets"],["the-two-ethiopias","The Two Ethiopias"]]},{"k":"miriam","n":"Miriam","t":"The prophetess.","r":3,"c":-1,"p":["amram"],"m":0,"w":null,"i":"miriam","sym":null,"v":[{"r":"Exo 15:20","t":"[20] And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."},{"r":"1 Chr 6:3","t":"[3] And the children of Amram; Aaron, and Moses, and Miriam. The sons also of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."}],"o":"","sc":[]},{"k":"aaron","n":"Aaron","t":"The first high priest.","r":3,"c":0,"p":["amram"],"m":1,"w":null,"i":"aaron","sym":null,"v":[{"r":"Exo 28:1","t":"[1] And take thou unto thee Aaron thy brother, and his sons with him, from among the children of Israel, that he may minister unto me in the priest’s office, even Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron’s sons."},{"r":"Num 20:23–29","t":"[23] And the LORD spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying, [24] Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah. [25] Take Aaron and Eleazar his son, and bring them up unto mount Hor: [26] And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people , and shall die there. [27] And Moses did as the LORD commanded: and they went up into mount Hor in the sight of all the congregation. [28] And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount. [29] And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel."}],"o":"","sc":[["the-lost-messiahs","The Scroll of the Lost Messiahs"],["hor","Hor"],["kadesh","Kadesh"],["the-masoretes","The Scroll of the Masoretes"]]},{"k":"korah","n":"Korah","t":"Rebelled against Aaron's office.","r":3,"c":2,"p":["izhar"],"m":0,"w":null,"i":"korah","sym":null,"v":[{"r":"Num 16:1–3,32","t":"[1] Now Korah, the son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took men: [2] And they rose up before Moses, with certain of the children of Israel, two hundred and fifty princes of the assembly, famous in the congregation, men of renown: [3] And they gathered themselves together against Moses and against Aaron, and said unto them, Ye take too much upon you, seeing all the congregation are holy, every one of them, and the LORD is among them: wherefore then lift ye up yourselves above the congregation of the LORD ? [32] And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods."}],"o":"","sc":[["the-complete-edom-compendium","The Complete Edom Compendium"]]},{"k":"nadab","n":"Nadab & Abihu","t":"Offered strange fire and died.","r":4,"c":-1,"p":["aaron"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"Lev 10:1–2","t":"[1] And Nadab and Abihu, the sons of Aaron, took either of them his censer, and put fire therein, and put incense thereon, and offered strange fire before the LORD , which he commanded them not. [2] And there went out fire from the LORD , and devoured them, and they died before the LORD ."}],"o":"","sc":[]},{"k":"eleazar","n":"Eleazar","t":"Son of Aaron. His line held the office.","r":4,"c":0,"p":["aaron"],"m":1,"w":null,"i":"eleazar","sym":null,"v":[{"r":"Num 20:28","t":"[28] And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."},{"r":"1 Chr 6:3–4","t":"[3] And the children of Amram; Aaron, and Moses, and Miriam. The sons also of Aaron; Nadab, and Abihu, Eleazar, and Ithamar. [4] Eleazar begat Phinehas, Phinehas begat Abishua,"}],"o":"","sc":[["hor","Hor"],["the-mighty-men","The Mighty Men"]]},{"k":"ithamar","n":"Ithamar","t":"Son of Aaron. Eight courses came from him.","r":4,"c":2,"p":["aaron"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 24:3–4","t":"[3] And David distributed them, both Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, according to their offices in their service. [4] And there were more chief men found of the sons of Eleazar than of the sons of Ithamar; and thus were they divided. Among the sons of Eleazar there were sixteen chief men of the house of their fathers, and eight among the sons of Ithamar according to the house of their fathers."}],"o":"","sc":[]},{"k":"phinehas","n":"Phinehas","t":"Received the covenant of an everlasting priesthood.","r":5,"c":0,"p":["eleazar"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Num 25:11–13","t":"[11] Phinehas, the son of Eleazar, the son of Aaron the priest, hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy. [12] Wherefore say, Behold, I give unto him my covenant of peace: [13] And he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel."}],"o":"","sc":[]},{"k":"eli","n":"Eli","t":"High priest at Shiloh, of Ithamar's line. The Ark was taken.","r":5,"c":2,"p":["ithamar"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Sam 1:9","t":"[9] So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD ."},{"r":"1 Sam 4:17–18","t":"[17] And the messenger answered and said, Israel is fled before the Philistines, and there hath been also a great slaughter among the people, and thy two sons also, Hophni and Phinehas, are dead, and the ark of God is taken. [18] And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."}],"o":"","sc":[]},{"k":"abishua","n":"Abishua","t":"Son of Phinehas.","r":6,"c":0,"p":["phinehas"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:4","t":"[4] Eleazar begat Phinehas, Phinehas begat Abishua,"}],"o":"","sc":[]},{"k":"hophni","n":"Hophni & Phinehas","t":"Sons of Eli, killed at Aphek.","r":6,"c":2,"p":["eli"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Sam 4:11","t":"[11] And the ark of God was taken; and the two sons of Eli, Hophni and Phinehas, were slain."}],"o":"","sc":[]},{"k":"bukki","n":"Bukki","t":"Son of Abishua.","r":7,"c":0,"p":["abishua"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:5","t":"[5] And Abishua begat Bukki, and Bukki begat Uzzi,"}],"o":"","sc":[]},{"k":"ahitub-e","n":"Ahitub","t":"Son of Phinehas, in Eli's line.","r":7,"c":2,"p":["hophni"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Sam 14:3","t":"[3] And Ahiah, the son of Ahitub, I-chabod’s brother, the son of Phinehas, the son of Eli, the LORD’s priest in Shiloh, wearing an ephod. And the people knew not that Jonathan was gone."}],"o":"","sc":[]},{"k":"uzzi","n":"Uzzi","t":"Son of Bukki.","r":8,"c":0,"p":["bukki"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:5","t":"[5] And Abishua begat Bukki, and Bukki begat Uzzi,"}],"o":"","sc":[]},{"k":"ahimelech","n":"Ahimelech","t":"Priest at Nob, killed at Saul's order.","r":8,"c":2,"p":["ahitub-e"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Sam 21:1","t":"[1] Then came David to Nob to Ahimelech the priest: and Ahimelech was afraid at the meeting of David, and said unto him, Why art thou alone, and no man with thee?"},{"r":"1 Sam 22:18","t":"[18] And the king said to Doeg, Turn thou, and fall upon the priests. And Doeg the Edomite turned, and he fell upon the priests, and slew on that day fourscore and five persons that did wear a linen ephod."}],"o":"","sc":[]},{"k":"zerahiah","n":"Zerahiah","t":"Son of Uzzi.","r":9,"c":0,"p":["uzzi"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:6","t":"[6] And Uzzi begat Zerahiah, and Zerahiah begat Meraioth,"}],"o":"","sc":[]},{"k":"abiathar","n":"Abiathar","t":"Escaped Nob, served David, removed by Solomon.","r":9,"c":2,"p":["ahimelech"],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"1 Sam 22:20","t":"[20] And one of the sons of Ahimelech the son of Ahitub, named Abiathar, escaped, and fled after David."},{"r":"1 Ki 2:26–27","t":"[26] And unto Abiathar the priest said the king, Get thee to Anathoth, unto thine own fields; for thou art worthy of death: but I will not at this time put thee to death, because thou barest the ark of the Lord GOD before David my father, and because thou hast been afflicted in all wherein my father was afflicted. [27] So Solomon thrust out Abiathar from being priest unto the LORD ; that he might fulfil the word of the LORD , which he spake concerning the house of Eli in Shiloh."}],"o":"","sc":[]},{"k":"meraioth","n":"Meraioth","t":"Son of Zerahiah.","r":10,"c":0,"p":["zerahiah"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:6–7","t":"[6] And Uzzi begat Zerahiah, and Zerahiah begat Meraioth, [7] Meraioth begat Amariah, and Amariah begat Ahitub,"}],"o":"","sc":[]},{"k":"amariah","n":"Amariah","t":"Son of Meraioth.","r":11,"c":0,"p":["meraioth"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:7","t":"[7] Meraioth begat Amariah, and Amariah begat Ahitub,"}],"o":"","sc":[]},{"k":"ahitub","n":"Ahitub","t":"Son of Amariah.","r":12,"c":0,"p":["amariah"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:7–8","t":"[7] Meraioth begat Amariah, and Amariah begat Ahitub, [8] And Ahitub begat Zadok, and Zadok begat Ahimaaz,"}],"o":"","sc":[]},{"k":"zadok","n":"Zadok","t":"High priest under David and Solomon. The line of the later priesthood.","r":13,"c":0,"p":["ahitub"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"2 Sam 8:17","t":"[17] And Zadok the son of Ahitub, and Ahimelech the son of Abiathar, were the priests; and Seraiah was the scribe;"},{"r":"1 Ki 2:35","t":"[35] And the king put Benaiah the son of Jehoiada in his room over the host: and Zadok the priest did the king put in the room of Abiathar."},{"r":"1 Chr 6:8","t":"[8] And Ahitub begat Zadok, and Zadok begat Ahimaaz,"}],"o":"","sc":[]},{"k":"ahimaaz","n":"Ahimaaz","t":"Son of Zadok.","r":14,"c":0,"p":["zadok"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"2 Sam 15:27","t":"[27] The king said also unto Zadok the priest, Art not thou a seer? return into the city in peace, and your two sons with you, Ahimaaz thy son, and Jonathan the son of Abiathar."},{"r":"1 Chr 6:8–9","t":"[8] And Ahitub begat Zadok, and Zadok begat Ahimaaz, [9] And Ahimaaz begat Azariah, and Azariah begat Johanan,"}],"o":"","sc":[]},{"k":"azariah1","n":"Azariah","t":"Son of Ahimaaz.","r":15,"c":0,"p":["ahimaaz"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:9","t":"[9] And Ahimaaz begat Azariah, and Azariah begat Johanan,"}],"o":"","sc":[]},{"k":"johanan1","n":"Johanan","t":"Son of Azariah.","r":16,"c":0,"p":["azariah1"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:9–10","t":"[9] And Ahimaaz begat Azariah, and Azariah begat Johanan, [10] And Johanan begat Azariah, (he it is that executed the priest’s office in the temple that Solomon built in Jerusalem:)"}],"o":"","sc":[]},{"k":"azariah2","n":"Azariah","t":"\"He it is that executed the priest's office in the temple.\"","r":17,"c":0,"p":["johanan1"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:10","t":"[10] And Johanan begat Azariah, (he it is that executed the priest’s office in the temple that Solomon built in Jerusalem:)"}],"o":"","sc":[]},{"k":"jehoiada","n":"Jehoiada","t":"Hid Joash and overthrew Athaliah. Scripture does not place him in the 1 Chronicles list.","r":17,"c":2,"p":[],"m":0,"w":null,"i":null,"sym":null,"v":[{"r":"2 Ki 11:4","t":"[4] And the seventh year Jehoiada sent and fetched the rulers over hundreds, with the captains and the guard, and brought them to him into the house of the LORD , and made a covenant with them, and took an oath of them in the house of the LORD , and shewed them the king’s son."},{"r":"2 Chr 24:15–16","t":"[15] But Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old was he when he died. [16] And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house."}],"o":"","sc":[]},{"k":"amariah2","n":"Amariah","t":"Chief priest under Jehoshaphat, if the same man.","r":18,"c":0,"p":["azariah2"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:11","t":"[11] And Azariah begat Amariah, and Amariah begat Ahitub,"},{"r":"2 Chr 19:11","t":"[11] And, behold, Amariah the chief priest is over you in all matters of the LORD ; and Zebadiah the son of Ishmael, the ruler of the house of Judah, for all the king’s matters: also the Levites shall be officers before you. Deal courageously, and the LORD shall be with the good."}],"o":"","sc":[]},{"k":"zechariah-j","n":"Zechariah","t":"Son of Jehoiada. Stoned in the Temple court.","r":18,"c":2,"p":["jehoiada"],"m":0,"w":null,"i":"zechariah-j","sym":null,"v":[{"r":"2 Chr 24:20–22","t":"[20] And the Spirit of God came upon Zechariah the son of Jehoiada the priest, which stood above the people, and said unto them, Thus saith God, Why transgress ye the commandments of the LORD , that ye cannot prosper? because ye have forsaken the LORD , he hath also forsaken you. [21] And they conspired against him, and stoned him with stones at the commandment of the king in the court of the house of the LORD . [22] Thus Joash the king remembered not the kindness which Jehoiada his father had done to him, but slew his son. And when he died, he said, The LORD look upon it , and require it ."}],"o":"","sc":[["the-sevenfold-fullness","The Sevenfold Fullness"],["the-great-scroll-of-the-horn","THE GREAT SCROLL OF THE HORN"],["the-lost-messiahs","The Scroll of the Lost Messiahs"]]},{"k":"ahitub2","n":"Ahitub","t":"Son of Amariah.","r":19,"c":0,"p":["amariah2"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:11","t":"[11] And Azariah begat Amariah, and Amariah begat Ahitub,"}],"o":"","sc":[]},{"k":"zadok2","n":"Zadok","t":"Son of Ahitub.","r":20,"c":0,"p":["ahitub2"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:12","t":"[12] And Ahitub begat Zadok, and Zadok begat Shallum,"}],"o":"","sc":[]},{"k":"shallum","n":"Shallum","t":"Son of Zadok.","r":21,"c":0,"p":["zadok2"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:12–13","t":"[12] And Ahitub begat Zadok, and Zadok begat Shallum, [13] And Shallum begat Hilkiah, and Hilkiah begat Azariah,"}],"o":"","sc":[]},{"k":"hilkiah","n":"Hilkiah","t":"Found the book of the law.","r":22,"c":0,"p":["shallum"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"2 Ki 22:8","t":"[8] And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD . And Hilkiah gave the book to Shaphan, and he read it."},{"r":"1 Chr 6:13","t":"[13] And Shallum begat Hilkiah, and Hilkiah begat Azariah,"}],"o":"","sc":[]},{"k":"azariah3","n":"Azariah","t":"Son of Hilkiah. A bulla bears his name, by most readings.","r":23,"c":0,"p":["hilkiah"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:13–14","t":"[13] And Shallum begat Hilkiah, and Hilkiah begat Azariah, [14] And Azariah begat Seraiah, and Seraiah begat Jehozadak,"}],"o":"","sc":[]},{"k":"seraiah","n":"Seraiah","t":"Chief priest at the fall, executed at Riblah.","r":24,"c":0,"p":["azariah3"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"2 Ki 25:18–21","t":"[18] And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door: [19] And out of the city he took an officer that was set over the men of war, and five men of them that were in the king’s presence, which were found in the city, and the principal scribe of the host, which mustered the people of the land, and threescore men of the people of the land that were found in the city: [20] And Nebuzar-adan captain of the guard took these, and brought them to the king of Babylon to Riblah: [21] And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land."},{"r":"1 Chr 6:14","t":"[14] And Azariah begat Seraiah, and Seraiah begat Jehozadak,"}],"o":"","sc":[]},{"k":"jehozadak","n":"Jehozadak","t":"Carried into captivity.","r":25,"c":0,"p":["seraiah"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"1 Chr 6:14–15","t":"[14] And Azariah begat Seraiah, and Seraiah begat Jehozadak, [15] And Jehozadak went into captivity , when the LORD carried away Judah and Jerusalem by the hand of Nebuchadnezzar."}],"o":"","sc":[]},{"k":"jeshua","n":"Jeshua","t":"Built the altar at the return.","r":26,"c":0,"p":["jehozadak"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Ezra 3:2","t":"[2] Then stood up Jeshua the son of Jozadak, and his brethren the priests, and Zerubbabel the son of Shealtiel, and his brethren, and builded the altar of the God of Israel, to offer burnt offerings thereon, as it is written in the law of Moses the man of God."},{"r":"Zec 3:1","t":"[1] And he shewed me Joshua the high priest standing before the angel of the LORD , and Satan standing at his right hand to resist him."}],"o":"","sc":[]},{"k":"joiakim","n":"Joiakim","t":"Son of Jeshua.","r":27,"c":0,"p":["jeshua"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Neh 12:10,26","t":"[10] And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada, [26] These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe."}],"o":"","sc":[]},{"k":"eliashib","n":"Eliashib","t":"Built the sheep gate.","r":28,"c":0,"p":["joiakim"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Neh 3:1","t":"[1] Then Eliashib the high priest rose up with his brethren the priests, and they builded the sheep gate; they sanctified it, and set up the doors of it; even unto the tower of Meah they sanctified it, unto the tower of Hananeel."},{"r":"Neh 13:4","t":"[4] And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, was allied unto Tobiah:"}],"o":"","sc":[]},{"k":"joiada","n":"Joiada","t":"A son married Sanballat's daughter.","r":29,"c":0,"p":["eliashib"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Neh 12:10–11","t":"[10] And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada, [11] And Joiada begat Jonathan, and Jonathan begat Jaddua."},{"r":"Neh 13:28","t":"[28] And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me."}],"o":"","sc":[]},{"k":"johanan2","n":"Johanan","t":"Named in Nehemiah, and in the Elephantine letter.","r":30,"c":0,"p":["joiada"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Neh 12:11,22–23","t":"[11] And Joiada begat Jonathan, and Jonathan begat Jaddua. [22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian. [23] The sons of Levi, the chief of the fathers, were written in the book of the chronicles, even until the days of Johanan the son of Eliashib."}],"o":"","sc":[]},{"k":"jaddua","n":"Jaddua","t":"The last high priest named in the Hebrew text.","r":31,"c":0,"p":["johanan2"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Neh 12:11,22","t":"[11] And Joiada begat Jonathan, and Jonathan begat Jaddua. [22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}],"o":"","sc":[]},{"k":"onias1","n":"Onias I","t":"Son of Jaddua, by Josephus.","r":32,"c":0,"p":["jaddua"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"Josephus, Ant. 11.347","sc":[]},{"k":"simon1","n":"Simon I","t":"Josephus calls him the Just.","r":33,"c":0,"p":["onias1"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"Josephus, Ant. 12.43","sc":[]},{"k":"onias2","n":"Onias II","t":"Withheld tribute from Ptolemy.","r":34,"c":0,"p":["simon1"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"Josephus, Ant. 12.158","sc":[]},{"k":"simon2","n":"Simon II","t":"Praised at length by Ben Sira.","r":35,"c":0,"p":["onias2"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"Sirach 50:1–21","sc":[]},{"k":"onias3","n":"Onias III","t":"The last of the old Zadokite line to serve. Murdered c. 171 BC.","r":36,"c":0,"p":["simon2"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"2 Macc 3:1; 4:33–34","sc":[]},{"k":"jason","n":"Jason, Menelaus, Alcimus","t":"Bought or appointed. The old line was broken.","r":37,"c":0,"p":["onias3"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"2 Macc 4:7–10,23–25; 1 Macc 7:9","sc":[]},{"k":"onias4","n":"Onias IV","t":"Fled to Egypt and built a temple at Leontopolis.","r":37,"c":2,"p":["onias3"],"m":0,"w":null,"i":null,"sym":null,"v":[],"o":"Josephus, Ant. 13.62–73","sc":[]},{"k":"jonathan","n":"Jonathan the Hasmonean","t":"Took the robe in 152 BC. Not of Zadok's house. The line changed.","r":38,"c":0,"p":["jason"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"1 Macc 10:20–21","sc":[]},{"k":"herodian","n":"The Herodian high priests","t":"Appointed and removed by rulers, 28 in all from Herod to the fall.","r":39,"c":0,"p":["jonathan"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"John 18:13","t":"[13] And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}],"o":"Josephus, Ant. 20.250","sc":[]},{"k":"caiaphas","n":"Caiaphas","t":"Son-in-law of Annas. Presided at the trial of Jesus.","r":40,"c":0,"p":["herodian"],"m":1,"w":null,"i":null,"sym":null,"v":[{"r":"Matt 26:57","t":"[57] And they that had laid hold on Jesus led him away to Caiaphas the high priest, where the scribes and the elders were assembled."},{"r":"John 18:13–14","t":"[13] And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year. [14] Now Caiaphas was he, which gave counsel to the Jews, that it was expedient that one man should die for the people."}],"o":"","sc":[]},{"k":"zacharias","n":"Zacharias","t":"A priest of the course of Abia, father of John the Baptist.","r":40,"c":2,"p":["herodian"],"m":0,"w":null,"i":"zacharias","sym":null,"v":[{"r":"Luke 1:5–13","t":"[5] There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth. [6] And they were both righteous before God, walking in all the commandments and ordinances of the Lord blameless. [7] And they had no child, because that Elisabeth was barren, and they both were now well stricken in years. [8] And it came to pass, that while he executed the priest’s office before God in the order of his course, [9] According to the custom of the priest’s office, his lot was to burn incense when he went into the temple of the Lord. [10] And the whole multitude of the people were praying without at the time of incense. [11] And there appeared unto him an angel of the Lord standing on the right side of the altar of incense. [12] And when Zacharias saw him , he was troubled, and fear fell upon him. [13] But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."}],"o":"","sc":[]},{"k":"phanni","n":"Phanni","t":"Chosen by lot by the Zealots. The last high priest.","r":41,"c":0,"p":["caiaphas"],"m":1,"w":null,"i":null,"sym":null,"v":[],"o":"Josephus, War 4.155","sc":[]},{"k":"john-b","n":"John the Baptist","t":"Son of a priest, sent to the wilderness.","r":41,"c":2,"p":["zacharias"],"m":0,"w":null,"i":"john-b","sym":null,"v":[{"r":"Luke 1:13–17","t":"[13] But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John. [14] And thou shalt have joy and gladness; and many shall rejoice at his birth. [15] For he shall be great in the sight of the Lord, and shall drink neither wine nor strong drink; and he shall be filled with the Holy Ghost, even from his mother’s womb. [16] And many of the children of Israel shall he turn to the Lord their God. [17] And he shall go before him in the spirit and power of Elias, to turn the hearts of the fathers to the children, and the disobedient to the wisdom of the just; to make ready a people prepared for the Lord."},{"r":"Luke 3:2–3","t":"[2] Annas and Caiaphas being the high priests, the word of God came unto John the son of Zacharias in the wilderness. [3] And he came into all the country about Jordan, preaching the baptism of repentance for the remission of sins;"}],"o":"","sc":[]}],"minc":-2,"maxc":2,"maxr":41,"sec":[[0,"Levi to Aaron"],[5,"Eleazar to the first Temple"],[13,"Zadok and the house"],[27,"The return"],[33,"Second Temple"],[37,"The broken line"]]};window.__P={"s":[{"t":"From Aaron to the first kings","x":"Scripture gives the line, with a break between Phinehas and Eli.","l":[{"n":"Aaron","d":"Wilderness","t":"First high priest.","r":"Exo 28:1; Num 20:23–29","v":[{"r":"Exo 28:1","t":"[1] And take thou unto thee Aaron thy brother, and his sons with him, from among the children of Israel, that he may minister unto me in the priest’s office, even Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron’s sons."},{"r":"Num 20:23–29","t":"[23] And the LORD spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying, [24] Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah. [25] Take Aaron and Eleazar his son, and bring them up unto mount Hor: [26] And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people , and shall die there. [27] And Moses did as the LORD commanded: and they went up into mount Hor in the sight of all the congregation. [28] And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount. [29] And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel."}],"o":""},{"n":"Eleazar","d":"Wilderness, conquest","t":"Served with Moses and Joshua. Divided the land.","r":"Num 20:28; Jos 14:1; 24:33","v":[{"r":"Num 20:28","t":"[28] And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."},{"r":"Jos 14:1","t":"[1] And these are the countries which the children of Israel inherited in the land of Canaan, which Eleazar the priest, and Joshua the son of Nun, and the heads of the fathers of the tribes of the children of Israel, distributed for inheritance to them."},{"r":"Jos 24:33","t":"[33] And Eleazar the son of Aaron died; and they buried him in a hill that pertained to Phinehas his son, which was given him in mount Ephraim."}],"o":""},{"n":"Phinehas","d":"Conquest, judges","t":"Stayed the plague and received the covenant of peace.","r":"Num 25:7–13; Jdg 20:28","v":[{"r":"Num 25:7–13","t":"[7] And when Phinehas, the son of Eleazar, the son of Aaron the priest, saw it , he rose up from among the congregation, and took a javelin in his hand; [8] And he went after the man of Israel into the tent, and thrust both of them through, the man of Israel, and the woman through her belly. So the plague was stayed from the children of Israel. [9] And those that died in the plague were twenty and four thousand. [10] And the LORD spake unto Moses, saying, [11] Phinehas, the son of Eleazar, the son of Aaron the priest, hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy. [12] Wherefore say, Behold, I give unto him my covenant of peace: [13] And he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel."},{"r":"Jdg 20:28","t":"[28] And Phinehas, the son of Eleazar, the son of Aaron, stood before it in those days,) saying, Shall I yet again go out to battle against the children of Benjamin my brother, or shall I cease? And the LORD said, Go up; for to morrow I will deliver them into thine hand."}],"o":""},{"n":"Eli","d":"c. 1100–1060 BC","t":"High priest at Shiloh, of the line of Ithamar.","r":"1 Sam 1:9; 4:18","v":[{"r":"1 Sam 1:9","t":"[9] So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD ."},{"r":"1 Sam 4:18","t":"[18] And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."}],"o":""},{"n":"Ahijah, Ahimelech","d":"Saul","t":"Priests of Eli's house. Those at Nob were killed.","r":"1 Sam 14:3; 22:18","v":[{"r":"1 Sam 14:3","t":"[3] And Ahiah, the son of Ahitub, I-chabod’s brother, the son of Phinehas, the son of Eli, the LORD’s priest in Shiloh, wearing an ephod. And the people knew not that Jonathan was gone."},{"r":"1 Sam 22:18","t":"[18] And the king said to Doeg, Turn thou, and fall upon the priests. And Doeg the Edomite turned, and he fell upon the priests, and slew on that day fourscore and five persons that did wear a linen ephod."}],"o":""},{"n":"Abiathar","d":"David","t":"Escaped Nob, removed by Solomon.","r":"1 Sam 22:20; 1 Ki 2:26–27","v":[{"r":"1 Sam 22:20","t":"[20] And one of the sons of Ahimelech the son of Ahitub, named Abiathar, escaped, and fled after David."},{"r":"1 Ki 2:26–27","t":"[26] And unto Abiathar the priest said the king, Get thee to Anathoth, unto thine own fields; for thou art worthy of death: but I will not at this time put thee to death, because thou barest the ark of the Lord GOD before David my father, and because thou hast been afflicted in all wherein my father was afflicted. [27] So Solomon thrust out Abiathar from being priest unto the LORD ; that he might fulfil the word of the LORD , which he spake concerning the house of Eli in Shiloh."}],"o":""},{"n":"Zadok","d":"David, Solomon","t":"Served beside Abiathar, then alone.","r":"2 Sam 8:17; 1 Ki 2:35","v":[{"r":"2 Sam 8:17","t":"[17] And Zadok the son of Ahitub, and Ahimelech the son of Abiathar, were the priests; and Seraiah was the scribe;"},{"r":"1 Ki 2:35","t":"[35] And the king put Benaiah the son of Jehoiada in his room over the host: and Zadok the priest did the king put in the room of Abiathar."}],"o":""}]},{"t":"The kingdom of Judah","x":"Dates are approximate. See Kings and Priests in Time for each beside his king.","l":[{"n":"Azariah son of Zadok","d":"c. 960–930 BC","t":"Named among Solomon's princes.","r":"1 Ki 4:2","v":[{"r":"1 Ki 4:2","t":"[2] And these were the princes which he had; Azariah the son of Zadok the priest,"}],"o":""},{"n":"Amariah","d":"c. 870–845 BC","t":"Over matters of the LORD under Jehoshaphat.","r":"2 Chr 19:11","v":[{"r":"2 Chr 19:11","t":"[11] And, behold, Amariah the chief priest is over you in all matters of the LORD ; and Zebadiah the son of Ishmael, the ruler of the house of Judah, for all the king’s matters: also the Levites shall be officers before you. Deal courageously, and the LORD shall be with the good."}],"o":""},{"n":"Jehoiada","d":"c. 841–800 BC","t":"Hid Joash and overthrew Athaliah. Buried among the kings.","r":"2 Ki 11:4; 2 Chr 24:15–16","v":[{"r":"2 Ki 11:4","t":"[4] And the seventh year Jehoiada sent and fetched the rulers over hundreds, with the captains and the guard, and brought them to him into the house of the LORD , and made a covenant with them, and took an oath of them in the house of the LORD , and shewed them the king’s son."},{"r":"2 Chr 24:15–16","t":"[15] But Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old was he when he died. [16] And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house."}],"o":""},{"n":"Azariah","d":"c. 790–750 BC","t":"With 80 priests withstood Uzziah.","r":"2 Chr 26:17–20","v":[{"r":"2 Chr 26:17–20","t":"[17] And Azariah the priest went in after him, and with him fourscore priests of the LORD , that were valiant men: [18] And they withstood Uzziah the king, and said unto him, It appertaineth not unto thee, Uzziah, to burn incense unto the LORD , but to the priests the sons of Aaron, that are consecrated to burn incense: go out of the sanctuary; for thou hast trespassed; neither shall it be for thine honour from the LORD God. [19] Then Uzziah was wroth, and had a censer in his hand to burn incense: and while he was wroth with the priests, the leprosy even rose up in his forehead before the priests in the house of the LORD , from beside the incense altar. [20] And Azariah the chief priest, and all the priests, looked upon him, and, behold, he was leprous in his forehead, and they thrust him out from thence; yea, himself hasted also to go out, because the LORD had smitten him."}],"o":""},{"n":"Urijah","d":"c. 735–720 BC","t":"Built the Damascus altar at Ahaz's command.","r":"2 Ki 16:10–16","v":[{"r":"2 Ki 16:10–16","t":"[10] And king Ahaz went to Damascus to meet Tiglath-pileser king of Assyria, and saw an altar that was at Damascus: and king Ahaz sent to Urijah the priest the fashion of the altar, and the pattern of it, according to all the workmanship thereof. [11] And Urijah the priest built an altar according to all that king Ahaz had sent from Damascus: so Urijah the priest made it against king Ahaz came from Damascus. [12] And when the king was come from Damascus, the king saw the altar: and the king approached to the altar, and offered thereon. [13] And he burnt his burnt offering and his meat offering, and poured his drink offering, and sprinkled the blood of his peace offerings, upon the altar. [14] And he brought also the brasen altar, which was before the LORD , from the forefront of the house, from between the altar and the house of the LORD , and put it on the north side of the altar. [15] And king Ahaz commanded Urijah the priest, saying, Upon the great altar burn the morning burnt offering, and the evening meat offering, and the king’s burnt sacrifice, and his meat offering, with the burnt offering of all the people of the land, and their meat offering, and their drink offerings; and sprinkle upon it all the blood of the burnt offering, and all the blood of the sacrifice: and the brasen altar shall be for me to enquire by . [16] Thus did Urijah the priest, according to all that king Ahaz commanded."}],"o":""},{"n":"Azariah of the house of Zadok","d":"c. 715–690 BC","t":"Answered Hezekiah about the offerings.","r":"2 Chr 31:10","v":[{"r":"2 Chr 31:10","t":"[10] And Azariah the chief priest of the house of Zadok answered him, and said, Since the people began to bring the offerings into the house of the LORD , we have had enough to eat, and have left plenty: for the LORD hath blessed his people; and that which is left is this great store."}],"o":""},{"n":"Hilkiah","d":"c. 640–610 BC","t":"Found the book of the law.","r":"2 Ki 22:8","v":[{"r":"2 Ki 22:8","t":"[8] And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD . And Hilkiah gave the book to Shaphan, and he read it."}],"o":""},{"n":"Seraiah","d":"590–586 BC","t":"Executed at Riblah.","r":"2 Ki 25:18–21","v":[{"r":"2 Ki 25:18–21","t":"[18] And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door: [19] And out of the city he took an officer that was set over the men of war, and five men of them that were in the king’s presence, which were found in the city, and the principal scribe of the host, which mustered the people of the land, and threescore men of the people of the land that were found in the city: [20] And Nebuzar-adan captain of the guard took these, and brought them to the king of Babylon to Riblah: [21] And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land."}],"o":""}]},{"t":"Return from exile","x":"The office passes from father to son in the books of Ezra and Nehemiah.","l":[{"n":"Jehozadak","d":"Exile","t":"Carried to Babylon.","r":"1 Chr 6:15","v":[{"r":"1 Chr 6:15","t":"[15] And Jehozadak went into captivity , when the LORD carried away Judah and Jerusalem by the hand of Nebuchadnezzar."}],"o":""},{"n":"Jeshua","d":"c. 538 BC","t":"Built the altar and Temple with Zerubbabel.","r":"Ezra 3:2; Zec 3:1","v":[{"r":"Ezra 3:2","t":"[2] Then stood up Jeshua the son of Jozadak, and his brethren the priests, and Zerubbabel the son of Shealtiel, and his brethren, and builded the altar of the God of Israel, to offer burnt offerings thereon, as it is written in the law of Moses the man of God."},{"r":"Zec 3:1","t":"[1] And he shewed me Joshua the high priest standing before the angel of the LORD , and Satan standing at his right hand to resist him."}],"o":""},{"n":"Joiakim","d":"After Jeshua","t":"Son of Jeshua.","r":"Neh 12:10,26","v":[{"r":"Neh 12:10,26","t":"[10] And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada, [26] These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe."}],"o":""},{"n":"Eliashib","d":"Days of Nehemiah","t":"Built the sheep gate, and gave Tobiah a chamber.","r":"Neh 3:1; 13:4–9","v":[{"r":"Neh 3:1","t":"[1] Then Eliashib the high priest rose up with his brethren the priests, and they builded the sheep gate; they sanctified it, and set up the doors of it; even unto the tower of Meah they sanctified it, unto the tower of Hananeel."},{"r":"Neh 13:4–9","t":"[4] And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, was allied unto Tobiah: [5] And he had prepared for him a great chamber, where aforetime they laid the meat offerings, the frankincense, and the vessels, and the tithes of the corn, the new wine, and the oil, which was commanded to be given to the Levites, and the singers, and the porters; and the offerings of the priests. [6] But in all this time was not I at Jerusalem: for in the two and thirtieth year of Artaxerxes king of Babylon came I unto the king, and after certain days obtained I leave of the king: [7] And I came to Jerusalem, and understood of the evil that Eliashib did for Tobiah, in preparing him a chamber in the courts of the house of God. [8] And it grieved me sore: therefore I cast forth all the household stuff of Tobiah out of the chamber. [9] Then I commanded, and they cleansed the chambers: and thither brought I again the vessels of the house of God, with the meat offering and the frankincense."}],"o":""},{"n":"Joiada","d":"After Eliashib","t":"A son married Sanballat's daughter and was driven out.","r":"Neh 12:10–11; 13:28","v":[{"r":"Neh 12:10–11","t":"[10] And Jeshua begat Joiakim, Joiakim also begat Eliashib, and Eliashib begat Joiada, [11] And Joiada begat Jonathan, and Jonathan begat Jaddua."},{"r":"Neh 13:28","t":"[28] And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me."}],"o":""},{"n":"Johanan","d":"c. 410 BC","t":"Named in Nehemiah and in the Elephantine letter.","r":"Neh 12:22–23","v":[{"r":"Neh 12:22–23","t":"[22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian. [23] The sons of Levi, the chief of the fathers, were written in the book of the chronicles, even until the days of Johanan the son of Eliashib."}],"o":""},{"n":"Jaddua","d":"Persian to Greek era","t":"Last high priest named in the Hebrew text.","r":"Neh 12:11,22","v":[{"r":"Neh 12:11,22","t":"[11] And Joiada begat Jonathan, and Jonathan begat Jaddua. [22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}],"o":""}]},{"t":"Greek rule","x":"The old line ends here, and the office is bought and sold.","l":[{"n":"Onias I","d":"c. 320–290 BC","t":"Son of Jaddua.","r":"Josephus, Ant. 11.347","v":[],"o":"Josephus, Ant. 11.347"},{"n":"Simon I","d":"c. 290–275 BC","t":"Josephus calls him the Just. Some give that title to Simon II.","r":"Josephus, Ant. 12.43","v":[],"o":"Josephus, Ant. 12.43"},{"n":"Eleazar","d":"c. 275–260 BC","t":"High priest in the Septuagint tradition.","r":"Josephus, Ant. 12.44","v":[],"o":"Josephus, Ant. 12.44"},{"n":"Manasseh","d":"c. 260–245 BC","t":"Followed Eleazar.","r":"Josephus, Ant. 12.157","v":[],"o":"Josephus, Ant. 12.157"},{"n":"Onias II","d":"c. 245–220 BC","t":"Withheld tribute from Ptolemy.","r":"Josephus, Ant. 12.158","v":[],"o":"Josephus, Ant. 12.158"},{"n":"Simon II","d":"c. 220–198 BC","t":"Repaired the Temple. Praised by Ben Sira.","r":"Sirach 50:1–21","v":[],"o":"Sirach 50:1–21"},{"n":"Onias III","d":"c. 198–175 BC","t":"Removed, and murdered about 171 BC.","r":"2 Macc 3:1; 4:33–34","v":[],"o":"2 Macc 3:1; 4:33–34"},{"n":"Jason","d":"175–172 BC","t":"Bought the office from Antiochus IV.","r":"2 Macc 4:7–10","v":[],"o":"2 Macc 4:7–10"},{"n":"Menelaus","d":"172–162 BC","t":"Outbid Jason, and took Temple vessels.","r":"2 Macc 4:23–32","v":[],"o":"2 Macc 4:23–32"},{"n":"Alcimus","d":"162–159 BC","t":"Set up by the Seleucids.","r":"1 Macc 7:9; 9:54–56","v":[],"o":"1 Macc 7:9; 9:54–56"}]},{"t":"Rival altars and rival priests","x":"While Jerusalem's office changed hands, others claimed the true line.","l":[{"n":"Onias IV","d":"c. 160 BC","t":"Built a temple at Leontopolis in Egypt, which stood until AD 73.","r":"Josephus, Ant. 13.62–73; War 7.420–436","v":[],"o":"Josephus, Ant. 13.62–73; War 7.420–436"},{"n":"Mount Gerizim","d":"c. 330–110 BC","t":"The Samaritan temple, destroyed by John Hyrcanus.","r":"Josephus, Ant. 11.310; 13.255–256","v":[],"o":"Josephus, Ant. 11.310; 13.255–256"},{"n":"The Teacher of Righteous","d":"2nd century BC","t":"Qumran's priestly founder, set against a \"Wicked Priest\" in Jerusalem. Neither is named.","r":"1QpHab 8–11; Damascus Document 1","v":[],"o":"1QpHab 8–11; Damascus Document 1"},{"n":"The sons of Zadok at Qumran","d":"2nd century BC to AD 68","t":"The community kept the Zadokite claim and its own calendar of the courses.","r":"1QS 5; 4Q320–330","v":[],"o":"1QS 5; 4Q320–330"}]},{"t":"Hasmonean priest-kings","x":"The office left Zadok's house.","l":[{"n":"Jonathan","d":"152–143 BC","t":"Appointed by Alexander Balas.","r":"1 Macc 10:20–21","v":[],"o":"1 Macc 10:20–21"},{"n":"Simon","d":"143–135 BC","t":"The people made the office hereditary.","r":"1 Macc 14:41","v":[],"o":"1 Macc 14:41"},{"n":"John Hyrcanus I","d":"135–104 BC","t":"Conquered Idumea, and destroyed Gerizim.","r":"Josephus, Ant. 13.254–258","v":[],"o":"Josephus, Ant. 13.254–258"},{"n":"Aristobulus I","d":"104–103 BC","t":"First to take the title of king.","r":"Josephus, Ant. 13.301","v":[],"o":"Josephus, Ant. 13.301"},{"n":"Alexander Jannaeus","d":"103–76 BC","t":"Fought a civil war with the Pharisees.","r":"Josephus, Ant. 13.372–383","v":[],"o":"Josephus, Ant. 13.372–383"},{"n":"Hyrcanus II","d":"76–67, 63–40 BC","t":"Restored by Pompey.","r":"Josephus, Ant. 14.73","v":[],"o":"Josephus, Ant. 14.73"},{"n":"Aristobulus II","d":"67–63 BC","t":"Taken to Rome by Pompey.","r":"Josephus, Ant. 14.79","v":[],"o":"Josephus, Ant. 14.79"},{"n":"Antigonus","d":"40–37 BC","t":"Set up by the Parthians, and beheaded.","r":"Josephus, Ant. 14.365; 15.8","v":[],"o":"Josephus, Ant. 14.365; 15.8"}]},{"t":"Herod and Rome","x":"Josephus counts 28 high priests from Herod to the fall (Ant. 20.250). Dates are his or are close estimates.","l":[{"n":"Ananel","d":"37–36 BC, 34 BC on","t":"Brought in by Herod.","r":"Josephus, Ant. 15.22","v":[],"o":"Josephus, Ant. 15.22"},{"n":"Aristobulus III","d":"36–35 BC","t":"Last Hasmonean priest, drowned at Herod's order.","r":"Josephus, Ant. 15.51–56","v":[],"o":"Josephus, Ant. 15.51–56"},{"n":"Jesus son of Phabes","d":"c. 30–23 BC","t":"Removed to make way for Simon.","r":"Josephus, Ant. 15.322","v":[],"o":"Josephus, Ant. 15.322"},{"n":"Simon son of Boethus","d":"23–5 BC","t":"Herod married his daughter.","r":"Josephus, Ant. 15.320–322","v":[],"o":"Josephus, Ant. 15.320–322"},{"n":"Matthias son of Theophilus","d":"5–4 BC","t":"Deposed after the golden eagle affair.","r":"Josephus, Ant. 17.78,164","v":[],"o":"Josephus, Ant. 17.78,164"},{"n":"Joseph son of Ellem","d":"One day","t":"Served when Matthias was unclean.","r":"Josephus, Ant. 17.166","v":[],"o":"Josephus, Ant. 17.166"},{"n":"Joazar son of Boethus","d":"4 BC, and again","t":"Removed by Archelaus, and later by Quirinius.","r":"Josephus, Ant. 17.164,339; 18.26","v":[],"o":"Josephus, Ant. 17.164,339; 18.26"},{"n":"Eleazar son of Boethus","d":"c. 4 BC","t":"Followed his brother.","r":"Josephus, Ant. 17.339","v":[],"o":"Josephus, Ant. 17.339"},{"n":"Jesus son of Sie","d":"c. 3 BC–AD 6","t":"Appointed by Archelaus.","r":"Josephus, Ant. 17.341","v":[],"o":"Josephus, Ant. 17.341"},{"n":"Annas","d":"AD 6–15","t":"Five sons held the office. Questioned Jesus.","r":"Luke 3:2; John 18:13; Josephus, Ant. 18.26; 20.198","v":[{"r":"Luke 3:2","t":"[2] Annas and Caiaphas being the high priests, the word of God came unto John the son of Zacharias in the wilderness."},{"r":"John 18:13","t":"[13] And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}],"o":"Josephus, Ant. 18.26; 20.198"},{"n":"Ishmael son of Phabi","d":"c. AD 15–16","t":"Appointed by Gratus.","r":"Josephus, Ant. 18.34","v":[],"o":"Josephus, Ant. 18.34"},{"n":"Eleazar son of Annas","d":"c. AD 16–17","t":"First of Annas's sons.","r":"Josephus, Ant. 18.34","v":[],"o":"Josephus, Ant. 18.34"},{"n":"Simon son of Camithus","d":"c. AD 17–18","t":"Served a single year.","r":"Josephus, Ant. 18.34","v":[],"o":"Josephus, Ant. 18.34"},{"n":"Caiaphas","d":"AD 18–36","t":"Presided at the trial of Jesus.","r":"Matt 26:57; John 11:49–50; Josephus, Ant. 18.35","v":[{"r":"Matt 26:57","t":"[57] And they that had laid hold on Jesus led him away to Caiaphas the high priest, where the scribes and the elders were assembled."},{"r":"John 11:49–50","t":"[49] And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all, [50] Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not."}],"o":"Josephus, Ant. 18.35"},{"n":"Jonathan son of Annas","d":"AD 36–37","t":"Appointed by Vitellius.","r":"Josephus, Ant. 18.95","v":[],"o":"Josephus, Ant. 18.95"},{"n":"Theophilus son of Annas","d":"AD 37–41","t":"Followed his brother.","r":"Josephus, Ant. 18.123","v":[],"o":"Josephus, Ant. 18.123"},{"n":"Simon Cantheras","d":"c. AD 41–42","t":"Appointed by Agrippa I.","r":"Josephus, Ant. 19.297","v":[],"o":"Josephus, Ant. 19.297"},{"n":"Matthias son of Annas","d":"c. AD 42–43","t":"Followed Simon.","r":"Josephus, Ant. 19.316","v":[],"o":"Josephus, Ant. 19.316"},{"n":"Elioneus","d":"c. AD 43–44","t":"Son of Cantheras.","r":"Josephus, Ant. 19.342","v":[],"o":"Josephus, Ant. 19.342"},{"n":"Joseph son of Camei","d":"c. AD 44–46","t":"Appointed by Herod of Chalcis.","r":"Josephus, Ant. 20.16","v":[],"o":"Josephus, Ant. 20.16"},{"n":"Ananias son of Nedebeus","d":"c. AD 47–59","t":"Ordered Paul struck on the mouth.","r":"Acts 23:2; 24:1; Josephus, Ant. 20.103","v":[{"r":"Acts 23:2","t":"[2] And the high priest Ananias commanded them that stood by him to smite him on the mouth."},{"r":"Acts 24:1","t":"[1] And after five days Ananias the high priest descended with the elders, and with a certain orator named Tertullus, who informed the governor against Paul."}],"o":"Josephus, Ant. 20.103"},{"n":"Ishmael son of Phabi II","d":"c. AD 59–61","t":"Appointed by Agrippa II.","r":"Josephus, Ant. 20.179","v":[],"o":"Josephus, Ant. 20.179"},{"n":"Joseph Cabi","d":"c. AD 61–62","t":"Son of Simon.","r":"Josephus, Ant. 20.196","v":[],"o":"Josephus, Ant. 20.196"},{"n":"Ananus son of Ananus","d":"AD 62","t":"Had James the brother of Jesus killed, and was removed.","r":"Josephus, Ant. 20.197–203","v":[],"o":"Josephus, Ant. 20.197–203"},{"n":"Jesus son of Damneus","d":"c. AD 62–63","t":"Followed Ananus.","r":"Josephus, Ant. 20.203","v":[],"o":"Josephus, Ant. 20.203"},{"n":"Jesus son of Gamaliel","d":"c. AD 63–64","t":"Followed Jesus son of Damneus.","r":"Josephus, Ant. 20.213","v":[],"o":"Josephus, Ant. 20.213"},{"n":"Matthias son of Theophilus","d":"c. AD 65–66","t":"In office when the war began.","r":"Josephus, Ant. 20.223","v":[],"o":"Josephus, Ant. 20.223"},{"n":"Phanni","d":"AD 67–70","t":"Chosen by lot by the Zealots. The last high priest.","r":"Josephus, War 4.147–157","v":[],"o":"Josephus, War 4.147–157"}]}],"c":[{"i":1,"n":"Jehoiarib","h":"יהויריב","town":"Meron","t":"First course. Mattathias, father of the Maccabees, came from it, and Josephus says his own family did too.","r":"1 Chr 24:7; 1 Macc 2:1; Josephus, Life 2","v":[{"r":"1 Chr 24:7","t":"[7] Now the first lot came forth to Jehoiarib, the second to Jedaiah,"}],"o":"1 Macc 2:1; Josephus, Life 2"},{"i":2,"n":"Jedaiah","h":"ידעיה","town":"Tzippori","t":"973 of the house of Jeshua returned from Babylon.","r":"1 Chr 24:7; Ezra 2:36; Zec 6:10","v":[{"r":"1 Chr 24:7","t":"[7] Now the first lot came forth to Jehoiarib, the second to Jedaiah,"},{"r":"Ezra 2:36","t":"[36] The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three."},{"r":"Zec 6:10","t":"[10] Take of them of the captivity, even of Heldai, of Tobijah, and of Jedaiah, which are come from Babylon, and come thou the same day, and go into the house of Josiah the son of Zephaniah;"}],"o":""},{"i":3,"n":"Harim","h":"חרם","town":"Fassuta","t":"1,017 returned. Some took foreign wives and put them away.","r":"1 Chr 24:8; Ezra 2:39; 10:21","v":[{"r":"1 Chr 24:8","t":"[8] The third to Harim, the fourth to Seorim,"},{"r":"Ezra 2:39","t":"[39] The children of Harim, a thousand and seventeen."},{"r":"Ezra 10:21","t":"[21] And of the sons of Harim; Maaseiah, and Elijah, and Shemaiah, and Jehiel, and Uzziah."}],"o":""},{"i":4,"n":"Seorim","h":"שערים","town":"Ayta ash-Shab or Ilut","t":"Named only in this list.","r":"1 Chr 24:8","v":[{"r":"1 Chr 24:8","t":"[8] The third to Harim, the fourth to Seorim,"}],"o":""},{"i":5,"n":"Malchijah","h":"מלכיה","town":"Bethlehem of Galilee","t":"Pashur son of Melchiah, who sought Jeremiah's death, is often placed here.","r":"1 Chr 24:9; Jer 21:1; 38:1; Neh 11:12","v":[{"r":"1 Chr 24:9","t":"[9] The fifth to Malchijah, the sixth to Mijamin,"},{"r":"Jer 21:1","t":"[1] The word which came unto Jeremiah from the LORD , when king Zedekiah sent unto him Pashur the son of Melchiah, and Zephaniah the son of Maaseiah the priest, saying,"},{"r":"Jer 38:1","t":"[1] Then Shephatiah the son of Mattan, and Gedaliah the son of Pashur, and Jucal the son of Shelemiah, and Pashur the son of Malchiah, heard the words that Jeremiah had spoken unto all the people, saying,"},{"r":"Neh 11:12","t":"[12] And their brethren that did the work of the house were eight hundred twenty and two: and Adaiah the son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashur, the son of Malchiah,"}],"o":""},{"i":6,"n":"Mijamin","h":"מימן","town":"Yodfat","t":"Returned with Zerubbabel, and sealed the covenant.","r":"1 Chr 24:9; Neh 10:7; 12:5","v":[{"r":"1 Chr 24:9","t":"[9] The fifth to Malchijah, the sixth to Mijamin,"},{"r":"Neh 10:7","t":"[7] Meshullam, Abijah, Mijamin,"},{"r":"Neh 12:5","t":"[5] Miamin, Maadiah, Bilgah,"}],"o":""},{"i":7,"n":"Hakkoz","h":"הקוץ","town":"Eilabun","t":"Called Koz. They could not prove their line, yet Meremoth son of Urijah later weighed the Temple silver.","r":"1 Chr 24:10; Ezra 2:61; 8:33; Neh 3:4","v":[{"r":"1 Chr 24:10","t":"[10] The seventh to Hakkoz, the eighth to Abijah,"},{"r":"Ezra 2:61","t":"[61] And of the children of the priests: the children of Habaiah, the children of Koz, the children of Barzillai; which took a wife of the daughters of Barzillai the Gileadite, and was called after their name:"},{"r":"Ezra 8:33","t":"[33] Now on the fourth day was the silver and the gold and the vessels weighed in the house of our God by the hand of Meremoth the son of Uriah the priest; and with him was Eleazar the son of Phinehas; and with them was Jozabad the son of Jeshua, and Noadiah the son of Binnui, Levites;"},{"r":"Neh 3:4","t":"[4] And next unto them repaired Meremoth the son of Urijah, the son of Koz. And next unto them repaired Meshullam the son of Berechiah, the son of Meshezabeel. And next unto them repaired Zadok the son of Baana."}],"o":""},{"i":8,"n":"Abijah","h":"אביה","town":"Kfar Uziel","t":"The course of Zacharias, father of John the Baptist.","r":"1 Chr 24:10; Neh 12:4; Luke 1:5","v":[{"r":"1 Chr 24:10","t":"[10] The seventh to Hakkoz, the eighth to Abijah,"},{"r":"Neh 12:4","t":"[4] Iddo, Ginnetho, Abijah,"},{"r":"Luke 1:5","t":"[5] There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}],"o":""},{"i":9,"n":"Jeshuah","h":"ישוע","town":"Arbel","t":"Possibly the house of Jeshua named at the return.","r":"1 Chr 24:11; Ezra 2:36","v":[{"r":"1 Chr 24:11","t":"[11] The ninth to Jeshua, the tenth to Shecaniah,"},{"r":"Ezra 2:36","t":"[36] The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy and three."}],"o":""},{"i":10,"n":"Shecaniah","h":"שכניה","town":"Kabul","t":"Named among those who returned, and among those who gave out portions under Hezekiah.","r":"1 Chr 24:11; 2 Chr 31:15; Neh 12:3","v":[{"r":"1 Chr 24:11","t":"[11] The ninth to Jeshua, the tenth to Shecaniah,"},{"r":"2 Chr 31:15","t":"[15] And next him were Eden, and Miniamin, and Jeshua, and Shemaiah, Amariah, and Shecaniah, in the cities of the priests, in their set office, to give to their brethren by courses, as well to the great as to the small:"},{"r":"Neh 12:3","t":"[3] Shechaniah, Rehum, Meremoth,"}],"o":""},{"i":11,"n":"Eliashib","h":"אלישיב","town":"Kafr Kana","t":"Shares his name with the high priest of Nehemiah's day.","r":"1 Chr 24:12","v":[{"r":"1 Chr 24:12","t":"[12] The eleventh to Eliashib, the twelfth to Jakim,"}],"o":""},{"i":12,"n":"Jakim","h":"יקים","town":"Safed","t":"Named only in this list.","r":"1 Chr 24:12","v":[{"r":"1 Chr 24:12","t":"[12] The eleventh to Eliashib, the twelfth to Jakim,"}],"o":""},{"i":13,"n":"Huppah","h":"חפה","town":"Beit Maon","t":"Named only in this list.","r":"1 Chr 24:13","v":[{"r":"1 Chr 24:13","t":"[13] The thirteenth to Huppah, the fourteenth to Jeshebeab,"}],"o":""},{"i":14,"n":"Jeshebeab","h":"ישבאב","town":"Shikhin","t":"Named only in this list.","r":"1 Chr 24:13","v":[{"r":"1 Chr 24:13","t":"[13] The thirteenth to Huppah, the fourteenth to Jeshebeab,"}],"o":""},{"i":15,"n":"Bilgah","h":"בלגה","town":"Maghar","t":"Returned with Zerubbabel. The Mishnah says its ring in the Temple court was fixed shut, because of Miriam of Bilgah.","r":"1 Chr 24:14; Neh 12:5,18; Mishnah Sukkah 5:8","v":[{"r":"1 Chr 24:14","t":"[14] The fifteenth to Bilgah, the sixteenth to Immer,"},{"r":"Neh 12:5,18","t":"[5] Miamin, Maadiah, Bilgah, [18] Of Bilgah, Shammua; of Shemaiah, Jehonathan;"}],"o":"Mishnah Sukkah 5:8"},{"i":16,"n":"Immer","h":"אמר","town":"Yavnit","t":"1,052 returned. Pashur son of Immer put Jeremiah in the stocks.","r":"1 Chr 24:14; Jer 20:1–2; Ezra 2:37; Neh 3:29","v":[{"r":"1 Chr 24:14","t":"[14] The fifteenth to Bilgah, the sixteenth to Immer,"},{"r":"Jer 20:1–2","t":"[1] Now Pashur the son of Immer the priest, who was also chief governor in the house of the LORD , heard that Jeremiah prophesied these things. [2] Then Pashur smote Jeremiah the prophet, and put him in the stocks that were in the high gate of Benjamin, which was by the house of the LORD ."},{"r":"Ezra 2:37","t":"[37] The children of Immer, a thousand fifty and two."},{"r":"Neh 3:29","t":"[29] After them repaired Zadok the son of Immer over against his house. After him repaired also Shemaiah the son of Shechaniah, the keeper of the east gate."}],"o":""},{"i":17,"n":"Hezir","h":"חזיר","town":"Kfar Mimlah","t":"A Kidron Valley tomb names priests of the sons of Hezir.","r":"1 Chr 24:15","v":[{"r":"1 Chr 24:15","t":"[15] The seventeenth to Hezir, the eighteenth to Aphses,"}],"o":""},{"i":18,"n":"Aphses (Happizzez)","h":"הפצץ","town":"Nazareth, or Daburiyya","t":"The Caesarea fragment ties this course to Nazareth, the oldest known Hebrew mention of the town.","r":"1 Chr 24:15","v":[{"r":"1 Chr 24:15","t":"[15] The seventeenth to Hezir, the eighteenth to Aphses,"}],"o":""},{"i":19,"n":"Pethahiah","h":"פתחיה","town":"Arraba","t":"A man of this name was among the Levites of Ezra's day.","r":"1 Chr 24:16; Ezra 10:23","v":[{"r":"1 Chr 24:16","t":"[16] The nineteenth to Pethahiah, the twentieth to Jehezekel,"},{"r":"Ezra 10:23","t":"[23] Also of the Levites; Jozabad, and Shimei, and Kelaiah, (the same is Kelita,) Pethahiah, Judah, and Eliezer."}],"o":""},{"i":20,"n":"Jehezekel","h":"יחזקאל","town":"Magdala","t":"Named only in this list. His name is Ezekiel.","r":"1 Chr 24:16","v":[{"r":"1 Chr 24:16","t":"[16] The nineteenth to Pethahiah, the twentieth to Jehezekel,"}],"o":""},{"i":21,"n":"Jachin","h":"יכין","town":"Deir Hanna or Kafr Inan","t":"Named among priests who lived in Jerusalem.","r":"1 Chr 24:17; 1 Chr 9:10; Neh 11:10","v":[{"r":"1 Chr 24:17","t":"[17] The one and twentieth to Jachin, the two and twentieth to Gamul,"},{"r":"1 Chr 9:10","t":"[10] And of the priests; Jedaiah, and Jehoiarib, and Jachin,"},{"r":"Neh 11:10","t":"[10] Of the priests: Jedaiah the son of Joiarib, Jachin."}],"o":""},{"i":22,"n":"Gamul","h":"גמול","town":"Kawkab al-Hawa","t":"Named only in this list.","r":"1 Chr 24:17","v":[{"r":"1 Chr 24:17","t":"[17] The one and twentieth to Jachin, the two and twentieth to Gamul,"}],"o":""},{"i":23,"n":"Delaiah","h":"דליהו","town":"Tzalmon","t":"Named only in this list among the courses.","r":"1 Chr 24:18","v":[{"r":"1 Chr 24:18","t":"[18] The three and twentieth to Delaiah, the four and twentieth to Maaziah."}],"o":""},{"i":24,"n":"Maaziah","h":"מעזיהו","town":"Hammat Tiberias","t":"Last course. An ossuary names Caiaphas's family with Maaziah.","r":"1 Chr 24:18; Neh 10:8","v":[{"r":"1 Chr 24:18","t":"[18] The three and twentieth to Delaiah, the four and twentieth to Maaziah."},{"r":"Neh 10:8","t":"[8] Maaziah, Bilgai, Shemaiah: these were the priests."}],"o":""}],"g":[{"n":"Ketef Hinnom amulets","w":"Jerusalem, found 1979. About 600 BC.","t":"Two tiny silver scrolls bearing words of the priestly blessing. They are the oldest known text of a passage from Scripture.","r":"Num 6:24–26","img":"ketef","v":[{"r":"Num 6:24–26","t":"[24] The LORD bless thee, and keep thee: [25] The LORD make his face shine upon thee, and be gracious unto thee: [26] The LORD lift up his countenance upon thee, and give thee peace."}],"o":""},{"n":"Azariah son of Hilkiah bulla","w":"City of David, Jerusalem. Before 586 BC.","t":"A clay seal impression naming a man most scholars connect with the high priestly family of Hilkiah. The identity is probable, not certain.","r":"1 Chr 6:13","img":"bulla","v":[{"r":"1 Chr 6:13","t":"[13] And Shallum begat Hilkiah, and Hilkiah begat Azariah,"}],"o":""},{"n":"Arad ostraca and shrine","w":"Arad, Negev. Before 586 BC.","t":"Letters on potsherds name priestly families such as Pashhur and Meremoth, and sons of Korah. A small shrine stood in the fortress.","r":"Jer 20:1; Ezra 8:33; 2 Chr 31:1","img":"arad","v":[{"r":"Jer 20:1","t":"[1] Now Pashur the son of Immer the priest, who was also chief governor in the house of the LORD , heard that Jeremiah prophesied these things."},{"r":"Ezra 8:33","t":"[33] Now on the fourth day was the silver and the gold and the vessels weighed in the house of our God by the hand of Meremoth the son of Uriah the priest; and with him was Eleazar the son of Phinehas; and with them was Jozabad the son of Jeshua, and Noadiah the son of Binnui, Levites;"},{"r":"2 Chr 31:1","t":"[1] Now when all this was finished, all Israel that were present went out to the cities of Judah, and brake the images in pieces, and cut down the groves, and threw down the high places and the altars out of all Judah and Benjamin, in Ephraim also and Manasseh, until they had utterly destroyed them all. Then all the children of Israel returned, every man to his possession, into their own cities."}],"o":""},{"n":"Elephantine letter","w":"Egypt, 407 BC.","t":"Jews in Egypt wrote to Bagohi, naming \"Johanan the high priest\" in Jerusalem. It independently matches Nehemiah's list.","r":"Neh 12:22","img":"elephantine","v":[{"r":"Neh 12:22","t":"[22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}],"o":""},{"n":"Yehud coins","w":"Judea, 4th century BC.","t":"Tiny silver coins, one naming \"Yohanan the priest.\" They show a priest's standing in Persian Judah.","r":"Neh 12:22","img":"yehud","v":[{"r":"Neh 12:22","t":"[22] The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, were recorded chief of the fathers: also the priests, to the reign of Darius the Persian."}],"o":""},{"n":"Mount Gerizim precinct","w":"Samaria. Excavated from 1983.","t":"The rival Samaritan sanctuary, which Josephus says was built for a priest driven from Jerusalem and destroyed by John Hyrcanus.","r":"Neh 13:28; Josephus, Ant. 11.302–325; 13.255–256","img":"gerizim","v":[{"r":"Neh 13:28","t":"[28] And one of the sons of Joiada, the son of Eliashib the high priest, was son in law to Sanballat the Horonite: therefore I chased him from me."}],"o":"Josephus, Ant. 11.302–325; 13.255–256"},{"n":"Hasmonean coins","w":"Judea, 2nd to 1st century BC.","t":"Bronze coins read \"Yehohanan the high priest\" and the like. They record the priest-kings in their own words.","r":"1 Macc 14:41; Josephus, Ant. 13.299","img":"hasmonean","v":[],"o":"1 Macc 14:41; Josephus, Ant. 13.299"},{"n":"Qumran course calendars","w":"Dead Sea caves. Before AD 68.","t":"Scrolls track the 24 courses week by week, proving how closely the rotation was followed.","r":"1 Chr 24:7–18; Luke 1:8; 4Q320–330","img":"qumran","v":[{"r":"1 Chr 24:7–18","t":"[7] Now the first lot came forth to Jehoiarib, the second to Jedaiah, [8] The third to Harim, the fourth to Seorim, [9] The fifth to Malchijah, the sixth to Mijamin, [10] The seventh to Hakkoz, the eighth to Abijah, [11] The ninth to Jeshua, the tenth to Shecaniah, [12] The eleventh to Eliashib, the twelfth to Jakim, [13] The thirteenth to Huppah, the fourteenth to Jeshebeab, [14] The fifteenth to Bilgah, the sixteenth to Immer, [15] The seventeenth to Hezir, the eighteenth to Aphses, [16] The nineteenth to Pethahiah, the twentieth to Jehezekel, [17] The one and twentieth to Jachin, the two and twentieth to Gamul, [18] The three and twentieth to Delaiah, the four and twentieth to Maaziah."},{"r":"Luke 1:8","t":"[8] And it came to pass, that while he executed the priest’s office before God in the order of his course,"}],"o":"4Q320–330"},{"n":"Tomb of the sons of Hezir","w":"Kidron Valley, Jerusalem.","t":"A Hebrew inscription names priests \"of the sons of Hezir,\" the seventeenth course.","r":"1 Chr 24:15","img":"hezir","v":[{"r":"1 Chr 24:15","t":"[15] The seventeenth to Hezir, the eighteenth to Aphses,"}],"o":""},{"n":"Temple warning inscription","w":"Jerusalem, found 1871.","t":"A Greek notice barring foreigners from the inner precinct on pain of death.","r":"Acts 21:28–29; Josephus, War 5.193–194","img":"warning","v":[{"r":"Acts 21:28–29","t":"[28] Crying out, Men of Israel, help: This is the man, that teacheth all men every where against the people, and the law, and this place: and further brought Greeks also into the temple, and hath polluted this holy place. [29] (For they had seen before with him in the city Trophimus an Ephesian, whom they supposed that Paul had brought into the temple.)"}],"o":"Josephus, War 5.193–194"},{"n":"Place of Trumpeting stone","w":"Temple Mount, found 1968.","t":"A broken Hebrew inscription from the corner where a priest sounded the trumpet for the Sabbath.","r":"Josephus, War 4.582","img":"trumpet","v":[],"o":"Josephus, War 4.582"},{"n":"Caiaphas ossuary","w":"Jerusalem, found 1990.","t":"An ornate bone box inscribed \"Joseph son of Caiaphas.\" Most scholars connect it with the high priest, though not all agree.","r":"Matt 26:3; John 18:13","img":"caiaphas","v":[{"r":"Matt 26:3","t":"[3] Then assembled together the chief priests, and the scribes, and the elders of the people, unto the palace of the high priest, who was called Caiaphas,"},{"r":"John 18:13","t":"[13] And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}],"o":""},{"n":"Miriam ossuary","w":"Seized from looters, published 2011.","t":"Inscribed for Miriam, daughter of Yeshua, son of Caiaphas, priest of Maaziah from Beth Imri. It ties the family to the last course. It has no recorded find-spot.","r":"1 Chr 24:18","img":"maaziah","v":[{"r":"1 Chr 24:18","t":"[18] The three and twentieth to Delaiah, the four and twentieth to Maaziah."}],"o":""},{"n":"Burnt House weight","w":"Jerusalem, destroyed AD 70.","t":"A stone weight marked for \"bar Kathros,\" a priestly family the Talmud remembers with complaint.","r":"Josephus, War 6.402–408; Talmud Pesachim 57a","img":"kathros","v":[],"o":"Josephus, War 6.402–408; Talmud Pesachim 57a"},{"n":"Gold bell","w":"Jerusalem drain, found 2011.","t":"A tiny gold bell, the kind worn on a garment. Its link to a priest is suggested, not proven.","r":"Exo 28:33–35","img":"bell","v":[{"r":"Exo 28:33–35","t":"[33] And beneath upon the hem of it thou shalt make pomegranates of blue, and of purple, and of scarlet, round about the hem thereof; and bells of gold between them round about: [34] A golden bell and a pomegranate, a golden bell and a pomegranate, upon the hem of the robe round about. [35] And it shall be upon Aaron to minister: and his sound shall be heard when he goeth in unto the holy place before the LORD , and when he cometh out, that he die not."}],"o":""},{"n":"Caesarea course inscription","w":"Caesarea, fragments found 1962. 3rd to 4th century AD.","t":"A synagogue list of the courses and their towns. It holds the first Hebrew mention of Nazareth.","r":"1 Chr 24:15","img":"caesarea","v":[{"r":"1 Chr 24:15","t":"[15] The seventeenth to Hezir, the eighteenth to Aphses,"}],"o":""},{"n":"Bayt Hadir column","w":"Yemen, found 1970.","t":"A stone column listing courses. Jews far from Galilee still kept the rotation in memory.","r":"1 Chr 24:7–18","img":"yemen","v":[{"r":"1 Chr 24:7–18","t":"[7] Now the first lot came forth to Jehoiarib, the second to Jedaiah, [8] The third to Harim, the fourth to Seorim, [9] The fifth to Malchijah, the sixth to Mijamin, [10] The seventh to Hakkoz, the eighth to Abijah, [11] The ninth to Jeshua, the tenth to Shecaniah, [12] The eleventh to Eliashib, the twelfth to Jakim, [13] The thirteenth to Huppah, the fourteenth to Jeshebeab, [14] The fifteenth to Bilgah, the sixteenth to Immer, [15] The seventeenth to Hezir, the eighteenth to Aphses, [16] The nineteenth to Pethahiah, the twentieth to Jehezekel, [17] The one and twentieth to Jachin, the two and twentieth to Gamul, [18] The three and twentieth to Delaiah, the four and twentieth to Maaziah."}],"o":""}]};